cmd:
cat > scripts/operations/compliance/check_governance.sh << 'EOF'
#!/usr/bin/env bash

# ABOUTME: Run governance checks for work-item and spec discipline
# ABOUTME: Wrapper for WRK location and WRK schema checks

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
MODE="warn"
SCOPE="changed"
BASE_REF="origin/main"

usage() {
  cat << USAGE
Usage: $(basename "$0") [--mode warn|gate] [--scope changed|all] [--base-ref <git-ref>]
USAGE
}

while [[ $# -gt 0 ]]; do
  case "$1" in
    --mode) MODE="${2:-warn}"; shift 2 ;;
    --scope) SCOPE="${2:-changed}"; shift 2 ;;
    --base-ref) BASE_REF="${2:-origin/main}"; shift 2 ;;
    -h|--help) usage; exit 0 ;;
    *) echo "Unknown option: $1" >&2; usage; exit 1 ;;
  esac
done

"$SCRIPT_DIR/audit_wrk_location.sh" --mode "$MODE" --scope "$SCOPE" --base-ref "$BASE_REF" --report /tmp/audit_wrk_location.json
"$SCRIPT_DIR/validate_work_queue_schema.sh" --mode "$MODE" --scope "$SCOPE" --base-ref "$BASE_REF" --report /tmp/validate
